-- ANTES: Redundância (NÃO NORMALIZADO)
CREATE TABLE user_lessons_flat (
  user_id UUID, user_email VARCHAR(255), user_name VARCHAR(255),
  lesson_id UUID, lesson_title VARCHAR(255), module_id UUID, module_name VARCHAR(255),
  progress_status VARCHAR(50)
);
-- Email armazenado 10x se usuário tem 10 lições
-- Mudar nome = 10 updates
-- Deletar última lição = deleta usuário

-- DEPOIS: Normalizado (3NF)
CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(255) UNIQUE);
CREATE TABLE modules (id UUID PRIMARY KEY, name VARCHAR(255));
CREATE TABLE lessons (id UUID PRIMARY KEY, module_id UUID, title VARCHAR(255));
CREATE TABLE user_lesson_progress (user_id UUID, lesson_id UUID, status VARCHAR(50));

-- Sem redundância, sem anomalias, mas precisa de JOINs
SELECT u.email, l.title, m.name, p.status
FROM users u
JOIN user_lesson_progress p ON u.id = p.user_id
JOIN lessons l ON p.lesson_id = l.id
JOIN modules m ON l.module_id = m.id
WHERE u.id = 'uuid';

-- Ruim: String sem validação
CREATE TABLE exercises (
  id UUID PRIMARY KEY,
  type VARCHAR(100), -- "multiple_choice", "code", "typo: muliple_choice"
  difficulty VARCHAR(100) -- "easy", "EASY", "easy ", sem padrão
);
SELECT * FROM exercises WHERE type = 'multiple choice'; -- 0 resultados (espaço!)

-- Melhor: Enum ou CHECK em banco
CREATE TABLE exercises (
  id UUID PRIMARY KEY,
  type VARCHAR(50) NOT NULL 
    CHECK (type IN ('multiple_choice', 'short_answer', 'code', 'essay')),
  difficulty VARCHAR(50) NOT NULL 
    CHECK (difficulty IN ('beginner', 'intermediate', 'advanced'))
);
INSERT INTO exercises VALUES (id, 'muliple_choice', ...); -- ERROR: invalid

-- Melhor ainda: PostgreSQL ENUM
CREATE TYPE exercise_type AS ENUM ('multiple_choice', 'short_answer', 'code', 'essay');
CREATE TABLE exercises (
  id UUID PRIMARY KEY,
  type exercise_type NOT NULL
);
